namespace sv_b6033b79497345b78645664f7b7f6af7.Services;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

public sealed class RecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = [
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic pizza with fresh mozzarella, tomatoes, and basil.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Creamy pasta with pancetta, egg yolk, and Pecorino Romano.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-soaked ladyfingers with mascarpone cream.", PrepTimeMinutes = 45 },
        ],
        [2] = [
            new() { Id = 4, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.", PrepTimeMinutes = 35 },
            new() { Id = 5, Title = "Green Curry", Description = "Aromatic coconut curry with vegetables and Thai basil.", PrepTimeMinutes = 40 },
            new() { Id = 6, Title = "Tom Yum Soup", Description = "Hot and sour soup with lemongrass, galangal, and prawns.", PrepTimeMinutes = 20 },
        ],
        [3] = [
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, onion, and cilantro.", PrepTimeMinutes = 50 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime, cilantro, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastry dusted with cinnamon sugar.", PrepTimeMinutes = 30 },
        ],
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (RecipesByCuisine.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (error is not null)
{
    <div class="alert alert-danger">
        <p>@error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    @{
        var displayed = Sort == "popular"
            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : recipes.OrderByDescending(r => r.Id).ToList();
    }

    <div class="row">
        @foreach (var recipe in displayed)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <p class="card-text"><small class="text-muted">Prep: @recipe.PrepTimeMinutes min</small></p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public int CuisineId { get; set; }
    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }

    private CancellationTokenSource? cts;
    private int? loadedCuisineId;
    private List<Recipe>? recipes;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == loadedCuisineId)
        {
            return;
        }

        loadedCuisineId = CuisineId;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cancellationToken);
            recipes = result;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Self-cancellation (parameter change or disposal) — stop silently.
            return;
        }
        catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
        {
            Logger.LogWarning(ex, "Request timed out loading recipes for cuisine {CuisineId}", CuisineId);
            error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load recipes for cuisine {CuisineId}", CuisineId);
            error = "Unable to load recipes. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

